update bm_execute_form_data set is_discard = true
where
product_plan_id = #{productPlanId}
and record_item_id = #{recordItemId}
and is_reuse = #{reuse}
and copy_version = #{copyVersion}
and is_discard = false

    and procedure_step_id = #{procedureStepId}

mapper.select:
select
    *
from bm_execute_form_data
where
product_plan_id = #{query.productPlanId}
and record_item_id = #{query.recordItemId}
and is_reuse = #{query.reuse}

    and copy_version = #{query.copyVersion}

and is_discard = false

    and procedure_step_id = #{query.procedureStepId}

and field_id in

    #{item}

select
*
from bm_execute_form_data
where
product_plan_id = #{query.productPlanId}
and record_item_id <> #{query.recordItemId}
and is_reuse = #{query.reuse}
and copy_version = #{query.copyVersion}
and is_discard = false

    and procedure_step_id <> #{query.procedureStepId}

and field_id in

    #{item}

select distinct bm_execute_form_data.id as form_data_id, bm_process.name as process_name, bm_procedure_model.name as procedure_name from bm_execute_form_data left join bm_process on bm_execute_form_data.process_id = bm_process.id and bm_process.is_deleted = 0 left join bm_procedure_step_model on bm_execute_form_data.procedure_step_model_id = bm_procedure_step_model.id and bm_procedure_step_model.is_deleted = 0 left join bm_procedure_model on bm_procedure_step_model.procedure_model_id = bm_procedure_model.id and bm_procedure_model.is_deleted = 0
bm_execute_form_data.id in
#{item}
order by bm_execute_form_data.id desc;
